impl Specification {
    /// The two directions, as one object. SEPARATE STAGE, deliberately.
    ///
    /// `def_eq_fuel_complete_wh3_final` is minted by `add_slot_dispatch_at`,
    /// which runs ~10 stages after `add_wh3_defeq_soundness`. Registering this
    /// beside the soundness chain would be a FORWARD REFERENCE:
    /// `add_recursive_def` elaborates against the live environment, so the
    /// constant is simply unknown at that point and the whole spec build aborts
    /// at this declaration. Hence its own stage, called after that one.
    pub(super) fn add_wh3_defeq_pair(&mut self) -> Result<(), SpecError> {
        self.add_recursive_def(
            SRC_DEF_EQ_WH3_SOUND_AND_COMPLETE,
            "def_eq_wh3_sound_and_complete: THE PAIR — both directions of the three-way conversion algorithm, over the same loop and the same acceptance object. \
\
Left: DefEq a b -> DefEqFuelAcceptsWh3 a b, which is def_eq_fuel_complete_wh3_final. Right: DefEqFuelAcceptsWh3 a b -> DefEq a b, which is def_eq_fuel_wh3_accepts_sound. Neither side carries an undischarged residual; the two accessibility premises are completeness's own and are what that direction genuinely needs, since the acceptance side ranges over raw untyped KExpr where reduction diverges. \
\
Recorded because the halves previously did NOT pair: completeness was proved at this three-way loop while the tree's only soundness statement was about the two-way loop. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_WH3_ROUNDTRIP_WITNESS,
            "def_eq_wh3_roundtrip_witness: THE ROUND TRIP, EXECUTED. Completeness turns DefEq (sort 0) (sort 0) into DefEqFuelAcceptsWh3 (sort 0) (sort 0); soundness turns it back. \\
\\
This is the non-vacuity evidence the pair needs, and it is stronger than an inhabitation check: a premise-free implication can still say nothing if its antecedent is empty, which is exactly how def_eq_fuel_complete went vacuous on a false hnf premise while showing 0 axioms and 0 domain axioms. Here the antecedent is not merely unrefuted — it is SUPPLIED, by the completeness half's own committed witness, so the two directions are demonstrated to compose on a real pair rather than to typecheck side by side. DerivedProved, zero axiom_deps.",
        )?;
        Ok(())
    }
}

const SRC_DEF_EQ_WH3_SOUND_AND_COMPLETE: &str = "def def_eq_wh3_sound_and_complete (a : KExpr) (acca : Wh3NormAcc a) (b : KExpr) (accb : Wh3NormAcc b) : AndType (DefEq a b -> DefEqFuelAcceptsWh3 a b) (DefEqFuelAcceptsWh3 a b -> DefEq a b) := AndType.intro (DefEq a b -> DefEqFuelAcceptsWh3 a b) (DefEqFuelAcceptsWh3 a b -> DefEq a b) (fun (hd : DefEq a b) => def_eq_fuel_complete_wh3_final a acca b hd accb) (fun (hacc : DefEqFuelAcceptsWh3 a b) => def_eq_fuel_wh3_accepts_sound a b hacc)";

const SRC_DEF_EQ_WH3_ROUNDTRIP_WITNESS: &str = "def def_eq_wh3_roundtrip_witness : DefEq (KExpr.sort Level.zero) (KExpr.sort Level.zero) := def_eq_fuel_wh3_accepts_sound (KExpr.sort Level.zero) (KExpr.sort Level.zero) def_eq_fuel_complete_wh3_final_witness";
